 activeCamera(){return this.lifeWalkMode?this.lifeWalkCamera:this.warmMode?this.warmCamera:this.borealMode?this.borealCamera:this.uplandMode?this.uplandCamera:this.yardangMode?this.yardangCamera:this.volcanicMode?this.volcanicCamera:this.fanMode?this.fanCamera:this.strataMode?this.strataCamera:this.saltMode?this.saltCamera:this.karstMode?this.karstCamera:this.geologyMode?this.geologyCamera:this.drylandMode?this.drylandCamera:this.tropicalMode?this.tropicalCamera:this.oceanMode?this.oceanCamera:this.polarMode?this.polarCamera:this.transportMode?this.transportCamera:this.productionMode?this.productionCamera:this.mountainMode?this.mountainCamera:this.underMode?this.undergroundCamera:this.marineMode?this.marineCamera:this.townMode?this.townCamera:this.camera;}
 bindZoom(){const panel=this.canvas.closest?.('.navigation');if(!panel?.querySelector)return;const frame=panel.querySelector('.navigation-frame');frame?.addEventListener('wheel',e=>{e.preventDefault();this.setZoom(this.miniView.zoom*Math.exp(-Math.max(-.3,Math.min(.3,e.deltaY*.0015))));},{passive:false});panel.querySelector('[data-mini-action=in]')?.addEventListener('click',()=>this.setZoom(this.miniView.zoom*1.25));panel.querySelector('[data-mini-action=out]')?.addEventListener('click',()=>this.setZoom(this.miniView.zoom/1.25));panel.querySelector('[data-mini-action=reset]')?.addEventListener('click',()=>this.setZoom(1));panel.querySelector('[data-mini-action=expand]')?.addEventListener('click',()=>panel.ownerDocument.getElementById('world-plan')?.click());this.miniScale=panel.querySelector('[data-mini-scale]');}
 setZoom(value){this.miniView.setZoom(value);for(const camera of Object.values(this))if(camera?.isOrthographicCamera)this.miniView.apply(camera,this.lastPosition);this.placeLabels();if(this.miniScale)this.miniScale.textContent=this.miniView.zoom.toFixed(1)+'×';}
 setRoute(stops,sampler){
  this.stops=stops;this.worldEntries=mapEntries(stops);this.entries=this.polarMode?this.polarEntries():this.transportMode?this.transportEntries():this.productionMode?this.productionEntries():this.mountainMode?this.mountainEntries():this.underMode?this.undergroundEntries():this.marineMode?this.marineEntries():this.townMode?this.townEntries():this.worldEntries;
  if(this.route){this.scene.remove(this.route);this.route.geometry.dispose();this.route.material.dispose();}
  const points=[];for(let i=0;i<=450;i++){const p=sampler(i/450);points.push(new THREE.Vector3(p.x,Math.max(p.y,0)+8,p.z));}
  this.route=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineDashedMaterial({color:'#ffdfa2',dashSize:20,gapSize:14,depthTest:false}));this.route.computeLineDistances();this.route.renderOrder=4;this.scene.add(this.route);
  this.drawNodes();
 }
 setLifeWalk(active){
  if(active&&!this.lifeWalkLine){
   const points=Array.from({length:260},(_,i)=>{
    const {x,z}=lifePoint(lifeLength*i/259);
    return new THREE.Vector3(x,walkingSurface(x,z)+13,z);
   });
   this.lifeWalkLine=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({
    color:'#ffdf8b',depthTest:false,depthWrite:false,toneMapped:false
   }));
   this.lifeWalkLine.renderOrder=5;this.scene.add(this.lifeWalkLine);
   this.lifeWalkCamera=new THREE.OrthographicCamera(-960,960,635,-635,1,6000);
   this.lifeWalkCamera.position.set(-835,2700,35);this.lifeWalkCamera.up.set(0,0,-1);
   this.lifeWalkCamera.lookAt(-835,0,35);
  }
  if(active)this.setMapLayer(false);
  this.lifeWalkMode=active;
  if(this.lifeWalkLine)this.lifeWalkLine.visible=active;
  this.route.visible=!active;
  const labels={farm:'农田',village:'榆湾村',dock:'码头',join:'汇口',wetland:'湿地',bay:'海湾'};
  this.entries=active?lifeStops.flatMap((stop,index)=>labels[stop.id]?
   [{...stop,...lifePoint(stop.at),terrain:labels[stop.id],stopIndex:index,current:true,route:'life-walk'}]:[]):this.worldEntries;
  this.drawNodes();
 }
 undergroundEntries(){return CAVE_SITES.map(r=>{const index=this.stops.findIndex(s=>s.id===r.id);return {...r,stopIndex:index>=0?index:constructionStops.findIndex(s=>s.id===r.id),current:index>=0,route:'build'};});}
 marineEntries(){return MARINE_SITES.map(r=>{const index=this.stops.findIndex(s=>s.id===r.id);return {...r,stopIndex:index>=0?index:constructionStops.findIndex(s=>s.id===r.id),current:index>=0,route:'build'};});}
 townEntries(){return SETTLEMENT_SITES.map(r=>{const index=this.stops.findIndex(s=>s.id===r.id);return {...r,stopIndex:index>=0?index:constructionStops.findIndex(s=>s.id===r.id),current:index>=0,route:'build'};});}
 mountainEntries(){return MOUNTAIN_SITES.map(r=>({...r,stopIndex:constructionStops.findIndex(s=>s.id===r.id),current:this.stops.some(s=>s.id===r.id),route:'build'}));}
 productionEntries(){return PRODUCTION_SITES.map(r=>({...r,stopIndex:constructionStops.findIndex(s=>s.id===r.id),current:this.stops.some(s=>s.id===r.id),route:'build'}));}
