 uplandEntries(){return UPLAND_SITES.map(r=>({...r,stopIndex:constructionStops.findIndex(s=>s.id===r.id),current:this.stops.some(s=>s.id===r.id),route:'build'}));}
 yardangEntries(){return YARDANG_SITES.map(r=>({...r,stopIndex:constructionStops.findIndex(s=>s.id===r.id),current:this.stops.some(s=>s.id===r.id),route:'build'}));}
 volcanicEntries(){return VOLCANIC_SITES.map(r=>({...r,stopIndex:constructionStops.findIndex(s=>s.id===r.id),current:this.stops.some(s=>s.id===r.id),route:'build'}));}
